// window.storage એ ફક્ત Claude Artifacts ની અંદર જ મળે છે.
// Vercel જેવી standalone site પર window.storage undefined હોય છે,
// એટલે localStorage વાપરીને એ જ API પૂરું પાડીએ છીએ, જેથી બંને જગ્યાએ ચાલે.
if (typeof window !== "undefined" && !window.storage) {
  window.storage = {
    async get(key, shared) {
      try {
        const raw = localStorage.getItem("apni_dukan_" + key);
        if (raw === null) throw new Error("not found");
        return { key, value: raw, shared: !!shared };
      } catch (e) {
        throw e;
      }
    },
    async set(key, value, shared) {
      try {
        localStorage.setItem("apni_dukan_" + key, value);
        return { key, value, shared: !!shared };
      } catch (e) {
        return null;
      }
    },
    async delete(key, shared) {
      try {
        localStorage.removeItem("apni_dukan_" + key);
        return { key, deleted: true, shared: !!shared };
      } catch (e) {
        return null;
      }
    },
    async list(prefix, shared) {
      try {
        const keys = [];
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith("apni_dukan_" + (prefix || ""))) {
            keys.push(k.replace("apni_dukan_", ""));
          }
        }
        return { keys, prefix, shared: !!shared };
      } catch (e) {
        return null;
      }
    },
  };
}

